//! End-to-end tests for `rwui create`.
//!
//! The command's unit tests check the generated bytes; these check the **shipped binary**: that
//! the argument parsing reaches `create`, that every profile writes the documented file set, and
//! that a second run into the same directory is refused instead of overwriting the project.

use std::path::{Path, PathBuf};
use std::process::{Command, Output};

fn rwui(args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_rwui")).args(args).output().expect("rwui must run")
}

fn code(output: &Output) -> i32 {
    output.status.code().unwrap_or(-1)
}

fn stderr(output: &Output) -> String {
    String::from_utf8_lossy(&output.stderr).into_owned()
}

fn stdout(output: &Output) -> String {
    String::from_utf8_lossy(&output.stdout).into_owned()
}

/// A scratch directory unique to this test, removed on drop.
struct Scratch(PathBuf);

impl Scratch {
    fn new(name: &str) -> Self {
        let path = std::env::temp_dir().join(format!("rwui-create-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&path);
        std::fs::create_dir_all(&path).expect("scratch dir");
        Self(path)
    }

    fn path(&self) -> &Path {
        &self.0
    }
}

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

/// The seven files every generated project carries, root-relative.
const PROJECT_FILES: [&str; 7] = [
    "Cargo.toml",
    "README.md",
    ".gitignore",
    "ui/app.json",
    "ui/app.css",
    "src/main.rs",
    "src/app.rs",
];

#[test]
fn every_profile_writes_the_documented_file_set() {
    let scratch = Scratch::new("profiles");
    for profile in ["desktop", "tablet", "mobile", "embedded", "mini"] {
        let name = format!("demo-{profile}");
        let output =
            rwui(&["create", &name, "--profile", profile, "-o", scratch.path().to_str().unwrap()]);
        assert_eq!(code(&output), 0, "{profile}: {}", stderr(&output));

        let root = scratch.path().join(&name);
        for file in PROJECT_FILES {
            let path = root.join(file);
            assert!(path.is_file(), "{profile}: {file} is missing at {}", path.display());
        }

        let manifest = std::fs::read_to_string(root.join("Cargo.toml")).expect("manifest");
        assert!(manifest.contains("default-features = false"), "{profile}: {manifest}");
        assert!(
            manifest.contains(&format!("features = [\"{profile}\"]")),
            "{profile}: the manifest names its profile: {manifest}"
        );
    }
}

#[test]
fn the_ui_pair_shares_its_base_name_and_the_document_parses() {
    let scratch = Scratch::new("ui-pair");
    let output = rwui(&["create", "demoapp", "-o", scratch.path().to_str().unwrap()]);
    assert_eq!(code(&output), 0, "{}", stderr(&output));

    let root = scratch.path().join("demoapp");
    let document = std::fs::read_to_string(root.join("ui/app.json")).expect("document");
    assert!(root.join("ui/app.css").is_file(), "the stylesheet sits beside the document");
    serde_json::from_str::<serde_json::Value>(&document).expect("the document is JSON");
}

#[test]
fn a_second_run_into_the_same_directory_is_refused() {
    let scratch = Scratch::new("refuse");
    let root = scratch.path().to_str().unwrap();
    let first = rwui(&["create", "demoapp", "-o", root]);
    assert_eq!(code(&first), 0, "{}", stderr(&first));

    let second = rwui(&["create", "demoapp", "-o", root]);
    assert_eq!(code(&second), 1, "a scaffold must not overwrite: {}", stderr(&second));
    assert!(stderr(&second).contains("RWCLI-012"), "{}", stderr(&second));
    assert!(stderr(&second).contains("already exists"), "{}", stderr(&second));
}

#[test]
fn an_invalid_package_name_is_reported() {
    let scratch = Scratch::new("bad-name");
    let output = rwui(&["create", "Demo", "-o", scratch.path().to_str().unwrap()]);
    assert_eq!(code(&output), 1, "{}", stderr(&output));
    assert!(stderr(&output).contains("lowercase"), "{}", stderr(&output));
}

#[test]
fn json_mode_keeps_progress_off_stdout() {
    let scratch = Scratch::new("json");
    let output = rwui(&["create", "demoapp", "-o", scratch.path().to_str().unwrap(), "--json"]);
    assert_eq!(code(&output), 0, "{}", stderr(&output));
    for line in stdout(&output).lines() {
        serde_json::from_str::<serde_json::Value>(line)
            .unwrap_or_else(|error| panic!("stdout must be NDJSON, got `{line}`: {error}"));
    }
    assert!(stderr(&output).contains("created "), "{}", stderr(&output));
}

#[test]
fn an_unknown_profile_is_a_usage_failure() {
    let output = rwui(&["create", "demoapp", "--profile", "watch"]);
    assert_eq!(code(&output), 2);
    assert!(stderr(&output).contains("unknown profile"), "{}", stderr(&output));
}
